namespace spotify {
namespace json {

/**
 * decode_exception objects are thrown when decoding fails, for example if the
 * JSON is invalid, or if the JSON doesn't conform to the specified schema.
 */
class decode_exception final : public std::runtime_error {
 public:
  explicit decode_exception(const char *what, size_t offset = 0);
  decode_exception(decode_exception &&exception, size_t offset);

  size_t offset() const {
    return _offset;
  }

 private:
  size_t _offset;
};

}  // namespace json
}  // namespace spotify

namespace spotify {
namespace json {

/**
 * encode_exception objects are thrown when encoding fails, for example when
 * trying to encode a null smart pointer or a NaN floating point number.
 */
class encode_exception final : public std::runtime_error {
 public:
  explicit json_never_inline encode_exception(const char *what);
};

}  // namespace json
}  // namespace spotify

namespace spotify {
namespace json {

/**
 * A decode_context has the information that is kept while decoding JSON with
 * codecs. It has information about the data to read and whether the decoding
 * has failed.
 */
struct decode_context final {
  decode_context(const char *begin, const char *end);
  decode_context(const char *data, size_t size);

  json_force_inline size_t offset() const {
    return (position - begin);
  }

  json_force_inline size_t offset(const ptrdiff_t d) const {
    return offset() + d;
  }

  json_force_inline size_t remaining() const {
    return (end - position);
  }

  const bool has_sse42;
  const char *position;
  const char *const begin;
  const char *const end;
};

}  // namespace json
}  // namespace spotify

namespace spotify {
namespace json {

/**
 * An encode_context has the information that is kept while encoding JSON with
 * codecs. It keeps a buffer of data that can be expanded and written to.
 */
struct encode_context final {
  encode_context(const std::size_t capacity = 4096);
  ~encode_context();

  json_force_inline char *reserve(const std::size_t reserved_bytes) {
    const auto remaining_bytes = static_cast<std::size_t>(_end - _ptr);  // _end is always >= _ptr
    if (json_likely(remaining_bytes >= reserved_bytes)) {
      return _ptr;
    } else {
      return grow_buffer(reserved_bytes);
    }
  }

  json_force_inline void advance(const std::size_t num_bytes) {
    _ptr += num_bytes;
  }

  json_force_inline void append(const char c) {
    reserve(1)[0] = c;
    advance(1);
  }

  json_force_inline void append_or_replace(const char replacing, const char with) {
    if (json_likely(!empty() && _ptr[-1] == replacing)) {
      _ptr[-1] = with;
    } else {
      append(with);
    }
  }

  json_force_inline void append(const void *data, const std::size_t size) {
    std::memcpy(reserve(size), data, size);
    advance(size);
  }

  json_never_inline void clear() {
    _ptr = _buf;
  }

  json_force_inline const char *data() const {
    return _buf;
  }

  json_force_inline std::size_t size() const {
    return static_cast<std::size_t>(_ptr - _buf);
  }

  json_force_inline std::size_t capacity() const {
    return _capacity;
  }

  json_force_inline bool empty() const {
    return (_ptr == _buf);
  }

  std::unique_ptr<void, decltype(std::free) *> steal_data();

  const bool has_sse42;

 private:
  char * grow_buffer(const std::size_t num_bytes);

  char *_buf;
  char *_ptr;
  const char *_end;
  std::size_t _capacity;
};

}  // namespace json
}  // namespace spotify

namespace spotify {
namespace json {
namespace detail {

struct encoded_value_base {
  struct unsafe_unchecked {};

 protected:
  void validate_json(const char *data, std::size_t size);
};

}  // namespace detail

struct encoded_value_ref : public detail::encoded_value_base {
  encoded_value_ref();
  encoded_value_ref(const encoded_value &value);
  explicit encoded_value_ref(const char *cstr);
  explicit encoded_value_ref(const char *cstr, const unsafe_unchecked &);
  explicit encoded_value_ref(const char *data, std::size_t size);
  explicit encoded_value_ref(const char *data, std::size_t size, const unsafe_unchecked &);

  template <typename value_with_data_and_size>
  explicit encoded_value_ref(const value_with_data_and_size &json);

  const char *data() const { return _data; }
  std::size_t size() const { return _size; }

  void swap(encoded_value_ref &value_ref);

 private:
  std::size_t _size;
  const char *_data;
};

struct encoded_value : public detail::encoded_value_base {
  encoded_value();
  encoded_value(encoded_value &&value) noexcept;
  encoded_value(const encoded_value &value);
  encoded_value(const encoded_value_ref &value_ref);
  ~encoded_value();

  explicit encoded_value(const char *cstr);
  explicit encoded_value(const char *cstr, const unsafe_unchecked &);
  explicit encoded_value(const char *data, std::size_t size);
  explicit encoded_value(const char *data, std::size_t size, const unsafe_unchecked &);
  explicit encoded_value(encode_context &&context);
  explicit encoded_value(encode_context &&context, const unsafe_unchecked &);

  template <typename value_with_data_and_size>
  explicit encoded_value(const value_with_data_and_size &json);

  encoded_value &operator=(encoded_value &&value) noexcept;
  encoded_value &operator=(const encoded_value &value);
  encoded_value &operator=(const encoded_value_ref &value_ref);

  const char *data() const { return static_cast<const char *>(_data.get()); }
  std::size_t size() const { return _size; }

  void swap(encoded_value &value);

 private:
  using data_buffer = std::unique_ptr<void, decltype(std::free) *>;
  std::size_t _size;
  data_buffer _data;
};

class codec_interface final {
 public:
  /**
   * This class exists only for documentation purposes.
   */
  codec_interface() = delete;

  /**
   * Typedef for the type that this codec pases to and from.
   */
  using object_type = void *;

  /**
   * Parse the given JSON. The string to parse begins at context.position and
   * ends at context.end. It is not an error if end is beyond the object that
   * this codec parses.
   *
   * If parsing succeeds, position should be set to point to the character after
   * the last character that was parsed. If parsing fails, context.error should
   * be set to a non-empty string and context.position should point to where the
   * error occured.
   *
   * If parsing fails, object_type should be ignored by the caller.
   *
   * decode will never be called with a contest that has_failed().
   */
  object_type decode(decode_context &context) const;

  /**
   * Write an object to an encoding context.
   */
  void encode(encode_context &context, const object_type &value) const;

  /**
   * This method is optional.
   *
   * If it is present and it returns false for a specific value, coders of JSON
   * objects will skip that value. This is necessary for codecs of types such as
   * boost::optional, where not even the key name or a comma should be printed if
   * the value is boost::none.
   *
   * The caller is responsible for not calling the encode method whenever this
   * method returns false. If the encode method is called anyway, an exception
   * should be thrown.
   */
  bool should_encode(const object_type &value) const;
};

class string_t final {
 public:
  using object_type = std::string;

  object_type decode(decode_context &context) const;
  void encode(encode_context &context, const object_type value) const;
};

template <>
struct default_codec_t<std::string> {
  static codec::string_t codec() {
    return codec::string_t();
  }
};

class boolean_t final {
 public:
  using object_type = bool;

  object_type decode(decode_context &context) const;
  void encode(encode_context &context, const object_type value) const;
};

template <>
struct default_codec_t<bool> {
  static codec::boolean_t codec() {
    return codec::boolean_t();
  }
};

namespace spotify {
namespace json {

struct null_type {};
static null_type null;

}
}

namespace spotify {
namespace json {

template <>
struct default_codec_t<null_type> {
  static codec::null_t<null_type> codec() {
    return codec::null_t<null_type>();
  }
};

}
}

struct sequence_inserter {
  using state = int;
  static const state init_state = 0;

  template <typename container_type, typename value_type>
  static state insert(
      decode_context &,
      state,
      container_type &container,
      value_type &&value) {
    container.push_back(std::forward<value_type>(value));
    return init_state;
  }

  template <typename container_type>
  static void validate(decode_context &, state, container_type &) {
    // Nothing to validate
  }
};

struct fixed_size_sequence_inserter {
  using state = size_t;
  static const state init_state = 0;

  template <typename container_type, typename value_type>
  static state insert(
      decode_context &context,
      state pos,
      container_type &container,
      value_type &&value) {
    fail_if(context, pos >= container.size(), "Too many elements in array");
    container[pos] = value;
    return pos + 1;
  }

  template <typename container_type>
  static void validate(decode_context &context, state pos, container_type &container) {
    fail_if(context, pos != container.size(), "Too few elements in array");
  }
};

struct associative_inserter {
  using state = int;
  static const state init_state = 0;

  template <typename container_type, typename value_type>
  static state insert(
      decode_context &,
      state,
      container_type &container,
      value_type &&value) {
    container.insert(std::forward<value_type>(value));
    return init_state;
  }

  template <typename container_type>
  static void validate(decode_context &, state, container_type &) {
    // Nothing to validate
  }
};

namespace spotify {
namespace json {
namespace codec {
namespace codec_detail {

struct object_t_base {
  ~object_t_base();

 protected:
  struct construct_untyped {
    virtual ~construct_untyped() = default;
  };

  object_t_base();
  object_t_base(construct_untyped *construct);
  object_t_base(object_t_base &&other);
  object_t_base(const object_t_base &other);

  void decode(decode_context &context, void *value) const;
  void encode(encode_context &context, const void *value) const;

  detail::field_registry _fields;

  /**
   * _construct may be unset, but only if T is default constructible. This is
   * enforced compile time by enabling the constructor that doesn't set it only
   * if T is default constructible.
   */
  std::shared_ptr<const construct_untyped> _construct;
};

}  // namespace codec_detail

class any_value_t final {
 public:
  using object_type = encoded_value_ref;

  object_type decode(decode_context &context) const;
  void encode(encode_context &context, const object_type &value) const;
};

template<>
struct default_codec_t<encoded_value> {
  static codec::any_value_t codec() {
    return codec::any_value();
  }
};

template<>
struct default_codec_t<encoded_value_ref> {
  static codec::any_value_t codec() {
    return codec::any_value();
  }
};

