// Exercise spotify::json::decode with multiple codec types over a fuzzed buffer.
// Requirements enforced:
// - If size > 0, data is non-null and valid via std::string storage.
// - Exactly-one-value constraint is left to the codec; parse errors are caught (function may throw).
{
  using namespace spotify::json;
  using namespace spotify::json::codec;

  // Generate arbitrary input buffer (1..4096 bytes). Data pointer remains valid for the scope.
  std::string buf = FUZZ_PARAM_STR();
  const char *data = buf.data();
  const size_t size = buf.size();

  // Randomly pick a codec to maximize coverage across template instantiations.
  unsigned int sel = *FUZZ_PARAM(unsigned int) % 3u;

  // 1) string_t codec
  if (sel == 0u) {
    string_t c;
    try {
      // object_type is std::string
      auto value = spotify::json::decode(c, data, size);
      // Re-encode to cover encode path if decoding succeeded
      encode_context enc;
      c.encode(enc, value);
      (void)enc.size();
    } catch (const std::exception &) {
      // Expected for invalid JSON for this codec; swallow per API contract (throws on error)
    }
  }

  // 2) boolean_t codec
  if (sel == 1u) {
    boolean_t c;
    try {
      // object_type is bool
      auto value = spotify::json::decode(c, data, size);
      // Re-encode to exercise the encode path
      encode_context enc;
      c.encode(enc, value);
      (void)enc.capacity();
    } catch (const std::exception &) {
      // Invalid JSON is common; ignore
    }
  }

  // 3) any_value_t codec (for arbitrary JSON values)
  if (sel == 2u) {
    any_value_t c;
    try {
      // object_type is encoded_value_ref (non-owning reference)
      auto value = spotify::json::decode(c, data, size);
      // Encode the value back out to exercise encoding of arbitrary values
      encode_context enc;
      c.encode(enc, value);
      // Touch the buffer to exercise append_or_replace path
      if (enc.size() > 0) { enc.append_or_replace('\n', ' '); }
    } catch (const std::exception &) {
      // Swallow per contract
    }
  }
}
// Validation: decode is called with valid buffers; exceptions are contained and no persistent objects are produced.

// Exercise spotify::json::try_decode with multiple codec types over fuzzed buffers.
// Requirements enforced:
// - Function is noexcept; we do not rely on exceptions.
// - If size == 0, must return false.
// - If size > 0, data is non-null and valid via std::string storage.
{
  using namespace spotify::json;
  using namespace spotify::json::codec;

  // Randomly decide to test the mandated empty-input fast path or a normal path.
  unsigned int mode = *FUZZ_PARAM(unsigned int) & 1u;

  if (mode == 0u) {
    // Empty input path must return false
    const char *data = nullptr; // data may be null when size == 0 by contract
    const size_t size = 0u;

    // Try with a couple of codecs to cover overloads
    {
      string_t c;
      string_t::object_type out; // std::string
      bool ok = spotify::json::try_decode(out, c, data, size);
      FUZZ_ASSERT(!ok, "try_decode must return false for size == 0");
    }
    {
      boolean_t c;
      boolean_t::object_type out = false; // bool
      bool ok = spotify::json::try_decode(out, c, data, size);
      FUZZ_ASSERT(!ok, "try_decode must return false for size == 0");
    }
  } else {
    // Non-empty buffer path: may succeed or fail, but must not throw
    std::string buf = FUZZ_PARAM_STR();
    const char *data = buf.data();
    const size_t size = buf.size();

    // Randomly pick a codec; on success, re-encode to cover more code.
    unsigned int sel = *FUZZ_PARAM(unsigned int) % 3u;

    if (sel == 0u) {
      string_t c;
      string_t::object_type out; // std::string
      bool ok = spotify::json::try_decode(out, c, data, size);
      if (ok) {
        encode_context enc;
        c.encode(enc, out);
        (void)enc.size();
      }
    } else if (sel == 1u) {
      boolean_t c;
      boolean_t::object_type out = false; // bool
      bool ok = spotify::json::try_decode(out, c, data, size);
      if (ok) {
        encode_context enc;
        c.encode(enc, out);
        (void)enc.capacity();
      }
    } else {
      any_value_t c;
      any_value_t::object_type out; // encoded_value_ref
      bool ok = spotify::json::try_decode(out, c, data, size);
      if (ok) {
        encode_context enc;
        c.encode(enc, out);
        if (!enc.empty()) { enc.append_or_replace('\n', ' '); }
      }
    }
  }
}
// Validation: empty-input branch asserts false return; non-empty branch avoids throwing and conditionally exercises encode paths.

// Generate a random branch to cover multiple codec/object combinations
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;

try {
  if (choice == 0) {
    // Case 0: Encode a std::string using codec::string_t
    spotify::json::codec::string_t codec;
    std::string s = FUZZ_PARAM_STR();
    // The codec must understand object_type = std::string
    // Invoke target function
    std::string out = spotify::json::encode(codec, s);
    // Property: if encode succeeded, resulting string should not contain stray nulls affecting size
    // (No strict property to assert here; accept any output)
    (void)out;
  } else if (choice == 1) {
    // Case 1: Encode a bool using codec::boolean_t
    spotify::json::codec::boolean_t codec;
    bool b = (*FUZZ_PARAM(unsigned int) % 2) != 0;
    std::string out = spotify::json::encode(codec, b);
    (void)out;
  } else {
    // Case 2: Encode an arbitrary encoded JSON value using codec::any_value_t
    spotify::json::codec::any_value_t codec;
    std::string payload = FUZZ_PARAM_STR();

    // Randomly choose whether to validate JSON (checked) or skip validation (unsafe)
    bool use_unchecked = (*FUZZ_PARAM(unsigned int) & 1) != 0;
    spotify::json::encoded_value_ref ref = use_unchecked
      ? spotify::json::encoded_value_ref(payload.data(), payload.size(), spotify::json::detail::encoded_value_base::unsafe_unchecked{})
      : spotify::json::encoded_value_ref(payload.data(), payload.size());

    // Invoke target function
    std::string out = spotify::json::encode(codec, ref);
    (void)out;
  }
} catch (const std::exception &) {
  // The API permits exceptions on invalid inputs or encoding failures; treat as expected fuzz path
  FUZZ_BAIL();
}

// Generate a random branch to cover multiple codec/value combinations
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
spotify::json::encoded_value *encoded = nullptr;

try {
  if (choice == 0) {
    // Case 0: Use codec::string_t with std::string
    spotify::json::codec::string_t codec;
    std::string s = FUZZ_PARAM_STR();
    spotify::json::encoded_value ev = spotify::json::encode_value(codec, s);
    // Move the returned value onto the heap so the fuzzer runtime can take ownership
    encoded = new spotify::json::encoded_value(std::move(ev));
  } else if (choice == 1) {
    // Case 1: Use codec::boolean_t with bool
    spotify::json::codec::boolean_t codec;
    bool b = (*FUZZ_PARAM(unsigned int) % 2) != 0;
    spotify::json::encoded_value ev = spotify::json::encode_value(codec, b);
    encoded = new spotify::json::encoded_value(std::move(ev));
  } else {
    // Case 2: Use codec::any_value_t with encoded_value_ref
    spotify::json::codec::any_value_t codec;
    std::string payload = FUZZ_PARAM_STR();

    // Randomly choose checked vs unchecked construction for coverage
    bool use_unchecked = (*FUZZ_PARAM(unsigned int) & 1) != 0;
    spotify::json::encoded_value_ref ref = use_unchecked
      ? spotify::json::encoded_value_ref(payload.data(), payload.size(), spotify::json::detail::encoded_value_base::unsafe_unchecked{})
      : spotify::json::encoded_value_ref(payload.data(), payload.size());

    spotify::json::encoded_value ev = spotify::json::encode_value(codec, ref);
    encoded = new spotify::json::encoded_value(std::move(ev));
  }
} catch (const std::exception &) {
  // Treat exceptions from codec/encoding as expected failure paths under fuzz
  FUZZ_BAIL();
}

// Ensure output is always non-null when we reach this point
if (!encoded) { FUZZ_BAIL(); }

// Provide 'encoded' to the fuzzer runtime as an output-owned object

// Exercise spotify::json::default_codec<T>() across several supported Ts and
// validate basic encode/decode round-trips. We avoid persisting any objects.
try {
  // Randomly choose a type specialization to instantiate and use.
  unsigned int which = *FUZZ_PARAM(unsigned int) % 3; // 0=string, 1=bool, 2=encoded_value_ref

  if (which == 0) {
    // T = std::string
    auto c = spotify::json::default_codec<std::string>();
    spotify::json::encode_context enc; // buffer to hold JSON
    std::string in = FUZZ_PARAM_STR();

    // Encode and ensure data was produced
    c.encode(enc, in);
    FUZZ_ASSERT(enc.size() > 0, "string codec produced no output");

    // Decode from the encoded buffer
    spotify::json::decode_context dec(enc.data(), enc.size());
    std::string out = c.decode(dec);

    // Property: round-trip should preserve the original string
    FUZZ_ASSERT(in == out, "string codec round-trip mismatch");

  } else if (which == 1) {
    // T = bool
    auto c = spotify::json::default_codec<bool>();
    spotify::json::encode_context enc;
    bool in = (*FUZZ_PARAM(unsigned int) % 2) != 0;

    c.encode(enc, in);
    FUZZ_ASSERT(enc.size() > 0, "bool codec produced no output");

    spotify::json::decode_context dec(enc.data(), enc.size());
    bool out = c.decode(dec);

    FUZZ_ASSERT(in == out, "bool codec round-trip mismatch");

  } else {
    // T = encoded_value_ref -> codec::any_value_t
    auto c = spotify::json::default_codec<spotify::json::encoded_value_ref>();

    // First, produce a known-valid JSON value via the string codec so we can
    // safely construct an encoded_value_ref that references valid JSON.
    auto sc = spotify::json::default_codec<std::string>();
    spotify::json::encode_context tmp;
    std::string payload = FUZZ_PARAM_STR();
    sc.encode(tmp, payload); // tmp now holds a valid JSON string literal

    // Construct a non-owning reference to that encoded JSON (skip revalidation)
    spotify::json::detail::encoded_value_base::unsafe_unchecked tag;
    spotify::json::encoded_value_ref evr(tmp.data(), tmp.size(), tag);

    // Encode evr via any_value codec into its own buffer
    spotify::json::encode_context enc;
    c.encode(enc, evr);
    FUZZ_ASSERT(enc.size() > 0, "any_value codec produced no output");

    // Decode back to an encoded_value_ref and ensure size/data are sensible
    spotify::json::decode_context dec(enc.data(), enc.size());
    spotify::json::encoded_value_ref out = c.decode(dec);
    FUZZ_ASSERT(out.data() != nullptr && out.size() > 0, "any_value decode invalid output");
  }
} catch (const std::exception &) {
  // Any exception (encode/decoded/validation) is considered a bail condition
  FUZZ_BAIL();
}

// Invoke the const accessor and validate against tracked attributes if present.
size_t got = exc->offset();
// Only assert when we know the expected value was tracked during construction.
const char *has = FUZZ_GET_ATTR_STR(exc, "has_offset");
if (has && has[0] != '\0') {
  int expected = FUZZ_GET_ATTR_INT(exc, "offset");
  FUZZ_ASSERT(got == static_cast<size_t>(expected), "decode_exception::offset must equal constructed offset");
}
// Property: idempotent/read-only; call twice and ensure stability.
size_t got2 = exc->offset();
FUZZ_ASSERT(got == got2, "decode_exception::offset should be stable across calls");

// Return the exception back to the pool as output (we do not free it here).

// Exercise both constructors of spotify::json::decode_exception and return two persistent outputs.
// 1) Direct construction from C-string and offset.
std::string what1 = FUZZ_PARAM_STR();
size_t off1 = static_cast<size_t>(*FUZZ_PARAM(unsigned int) % 1025); // keep small for speed
spotify::json::decode_exception *ex1 = new spotify::json::decode_exception(what1.c_str(), off1);
// Validate invariant: reported offset equals the provided offset.
FUZZ_ASSERT(ex1->offset() == off1, "decode_exception::offset mismatch after direct construction");
// Track attributes for downstream stubs (e.g., offset()).
FUZZ_SET_ATTR_INT(ex1, "offset", static_cast<int>(off1));
FUZZ_SET_ATTR_STR(ex1, "has_offset", "1");

// 2) Move-construction from an existing exception plus a new offset.
std::string what2 = FUZZ_PARAM_STR();
size_t off_src = static_cast<size_t>(*FUZZ_PARAM(unsigned int) % 1025);
size_t off_moved = static_cast<size_t>(*FUZZ_PARAM(unsigned int) % 1025);
// Source exception on the stack; it will be moved-from and then discarded.
spotify::json::decode_exception src(what2.c_str(), off_src);
spotify::json::decode_exception *ex2 = new spotify::json::decode_exception(std::move(src), off_moved);
// Validate invariant for moved-into object.
FUZZ_ASSERT(ex2->offset() == off_moved, "decode_exception::offset mismatch after move construction");
// Track attributes for downstream validation.
FUZZ_SET_ATTR_INT(ex2, "offset", static_cast<int>(off_moved));
FUZZ_SET_ATTR_STR(ex2, "has_offset", "1");

// Validation summary: both constructors are exercised; offsets are asserted to match inputs.
// Both ex1 and ex2 are non-null persistent outputs returned to the pool.

// Generate a non-null, null-terminated C-string message for the exception
std::string msg = FUZZ_PARAM_STR();
// msg.c_str() is guaranteed non-null and null-terminated

// Construct the encode_exception on the heap so it can be returned as an output
spotify::json::encode_exception *exc = new spotify::json::encode_exception(msg.c_str());

// Basic property: what() must be non-null and should equal the provided message text
FUZZ_ASSERT(exc != nullptr, "heap allocation failed");
FUZZ_ASSERT(exc->what() != nullptr, "encode_exception::what() returned null");
FUZZ_ASSERT(std::string(exc->what()) == std::string(msg.c_str()), "encode_exception message mismatch");

