// Construct a concrete transform codec instance around a string inner codec.
// Outward type: bool; Inner type: std::string.
// - encode_transform: bool -> std::string ("true"/"false")
// - decode_transform: std::string -> bool (accepts "true"/"false"/"1"/"0"; otherwise throws)
// Build a valid JSON string buffer from fuzz data and decode via the transform codec.
{
  // Create a small, valid JSON string from fuzz data by quoting and escaping.
  std::string raw = FUZZ_PARAM_STR();
  if (raw.size() > 128) raw.resize(128);  // cap size for performance
  std::string escaped;
  escaped.reserve(raw.size() * 2 + 2);
  for (unsigned char c : raw) {
    if (c == '"' || c == '\\') { escaped.push_back('\\'); escaped.push_back(static_cast<char>(c)); }
    else if (c < 0x20) { escaped.push_back(' '); } // avoid invalid control chars in JSON strings
    else { escaped.push_back(static_cast<char>(c)); }
  }
  std::string json_string;
  json_string.reserve(escaped.size() + 2);
  json_string.push_back('"');
  json_string.append(escaped);
  json_string.push_back('"');

  // Local decode_context over our well-formed JSON string literal.
  spotify::json::decode_context ctx(json_string.data(), json_string.size());

  // Concrete inner codec and transforms.
  spotify::json::codec::string_t inner;
  auto enc = [](const bool v) -> std::string { return v ? std::string("true") : std::string("false"); };
  auto dec = [](const std::string &s) -> bool {
    if (s == "true" || s == "1") return true;
    if (s == "false" || s == "0") return false;
    // Throw a decode_exception to exercise transform_t::decode error path.
    throw spotify::json::decode_exception("invalid boolean text");
  };

  // Build the transform codec and attempt to decode.
  auto t = spotify::json::codec::transform(inner, enc, dec);
  try {
    (void)t.decode(ctx); // value is bool; we discard it here
  } catch (const spotify::json::decode_exception &) {
    // Expected for most random strings; transform_t::decode should propagate with proper offset internally.
  }

  // Validation: ensure context advanced at least by 0 bytes and at most full buffer size.
  // Property: offset() must be <= size() and remaining() must be size() - offset().
  const size_t off = ctx.offset();
  const size_t rem = ctx.remaining();
  const size_t total = json_string.size();
  FUZZ_ASSERT(off <= total, "decode_context offset beyond end after transform_t::decode");
  FUZZ_ASSERT(rem + off == total, "decode_context remaining+offset mismatch after transform_t::decode");

  // Validation summary: This stub constructs a concrete transform codec, feeds a valid JSON string,
  // and exercises both success and failure paths by catching decode_exception.
}

