// Harness for enumeration_t<Outer, std::string>::decode
// Build an enumeration codec mapping enum values to simple alnum strings, then
// construct matching JSON input and decode, asserting mapping and context advance.
{
  using namespace spotify::json;
  using namespace spotify::json::codec;

  enum class Outer : int { A = 0, B = 1, C = 2 };

  auto make_alnum = [&](std::string s) {
    std::string out; out.reserve(16);
    for (char c : s) { if ((c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) { out.push_back(c); if (out.size() >= 16) break; } }
    if (out.empty()) out = "x"; // ensure JSON-safe simple string
    return out;
  };
  std::string sA = make_alnum(FUZZ_PARAM_STR());
  std::string sB = make_alnum(FUZZ_PARAM_STR());
  std::string sC = make_alnum(FUZZ_PARAM_STR());

  // Use the overload that infers the inner codec via default_codec<InnerObject>
  auto e = enumeration<Outer, std::string>({
    { Outer::A, sA },
    { Outer::B, sB },
    { Outer::C, sC }
  });

  // Pick one mapped entry to guarantee successful decode
  unsigned pick = (*FUZZ_PARAM(unsigned int)) % 3u;
  const std::string &chosen = (pick == 0 ? sA : (pick == 1 ? sB : sC));

  // Prepare JSON string token for chosen inner value
  std::string json; json.reserve(chosen.size() + 2);
  json.push_back('"'); json.append(chosen); json.push_back('"');

  // Fresh decode_context over prepared JSON
  decode_context ctx(json.data(), json.size());
  const size_t start_off = ctx.offset();

  // Invoke target decode
  Outer out = e.decode(ctx);

  // Validate: mapping correctness and that input advanced
  Outer expected = (pick == 0 ? Outer::A : (pick == 1 ? Outer::B : Outer::C));
  FUZZ_ASSERT(out == expected, "enumeration_t::decode returned unexpected value");
  FUZZ_ASSERT(ctx.offset() > start_off, "decode_context did not advance during decode");
}

