// Minimal JSON string escaper for control, quote, and backslash
auto escape_json = [](const std::string &in) {
  std::string out; out.reserve(in.size() + 16);
  const char *hex = "0123456789abcdef";
  for (unsigned char c : in) {
    switch (c) {
      case '"': out += "\\\""; break;
      case '\\': out += "\\\\"; break;
      case '\b': out += "\\b"; break;
      case '\f': out += "\\f"; break;
      case '\n': out += "\\n"; break;
      case '\r': out += "\\r"; break;
      case '\t': out += "\\t"; break;
      default:
        if (c < 0x20) {
          char buf[6];
          buf[0] = 'u'; buf[1] = '0'; buf[2] = '0';
          buf[3] = hex[(c >> 4) & 0xF];
          buf[4] = hex[c & 0xF];
          std::string esc = "\\"; esc += buf, out += esc;
        } else {
          out.push_back(static_cast<char>(c));
        }
    }
  }
  return out;
};

