import random
import string
from typing import List

# This generator produces valid JSON buffers tailored to exercise the provided
# fuzzing stubs, which expect JSON for various codecs: strings, booleans,
# numbers, null, arrays, objects, tuples/pairs, optional, maps/sets, and
# any_value. It focuses on generating well-formed JSON with diverse shapes,
# sizes, and edge cases, while staying under 4096 bytes.

# Utilities

def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    # Avoid control characters; include some punctuation that often needs escaping
    alphabet = string.ascii_letters + string.digits + " -_.,:/@#()[]{}+*?=|~"
    s = ''.join(rng.choice(alphabet) for _ in range(n))
    return s

def _escape_json_string(s: str) -> str:
    out = []
    for ch in s:
        c = ord(ch)
        if ch == '"' or ch == "\\":
            out.append('\\' + ch)
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif c < 0x20:
            out.append('\\u%04x' % c)
        else:
            out.append(ch)
    return '"' + ''.join(out) + '"'

def _rand_json_string(rng: random.Random, min_len: int = 0, max_len: int = 64) -> str:
    # Include some chance of empty string, long strings, and strings with escapables
    base = _rand_ascii(rng, min_len, max_len)
    # Occasionally insert quotes/backslashes/newlines to exercise escaping
    if base and rng.random() < 0.35:
        insertables = ['"', '\\', '\n', '\t', '\r']
        pos = rng.randrange(0, len(base))
        base = base[:pos] + rng.choice(insertables) + base[pos:]
    return _escape_json_string(base)

def _rand_boolean(rng: random.Random) -> str:
    return 'true' if rng.random() < 0.5 else 'false'

def _rand_number(rng: random.Random) -> str:
    # Produce integers and floating-point forms, including exponents and negatives
    kind = rng.random()
    if kind < 0.4:
        # Small integer
        val = rng.randint(-1000000, 1000000)
        return str(val)
    elif kind < 0.8:
        # Float with decimal and optional exponent
        sign = '-' if rng.random() < 0.3 else ''
        whole = str(rng.randint(0, 999999))
        frac = ''.join(rng.choice(string.digits) for _ in range(rng.randint(1, 6)))
        s = f"{sign}{whole}.{frac}"
        if rng.random() < 0.5:
            exp_sign = '+' if rng.random() < 0.5 else '-'
            exp = rng.randint(0, 308)
            s += f"e{exp_sign}{exp}"
        return s
    else:
        # Edgey representations like 0, -0, leading zeros (valid JSON number forbids leading zeros unless zero itself)
        return '0' if rng.random() < 0.7 else '-0'

def _rand_null(rng: random.Random) -> str:
    return 'null'

def _rand_array(rng: random.Random, depth: int, budget: int) -> str:
    # Create arrays with mixed types while controlling size
    n = rng.randint(0, 6)
    elems: List[str] = []
    size = 2  # brackets
    for _ in range(n):
        if size > budget:
            break
        v = _rand_value(rng, depth + 1, max(0, budget - size - 2))
        elems.append(v)
        size += len(v) + 1
    return '[' + ','.join(elems) + ']'

def _rand_object(rng: random.Random, depth: int, budget: int) -> str:
    # Generate objects with string keys and diverse values
    n = rng.randint(0, 6)
    items = []
    size = 2
    for _ in range(n):
        if size > budget:
            break
        key = _rand_json_string(rng, 0, 16)
        val = _rand_value(rng, depth + 1, max(0, budget - size - 2 - len(key)))
        pair = key + ':' + val
        items.append(pair)
        size += len(pair) + 1
    return '{' + ','.join(items) + '}'

def _rand_value(rng: random.Random, depth: int, budget: int) -> str:
    # Bias towards primitives at deeper recursion
    if depth > 3:
        choice = rng.random()
        if choice < 0.3:
            return _rand_json_string(rng)
        elif choice < 0.6:
            return _rand_number(rng)
        elif choice < 0.8:
            return _rand_boolean(rng)
        else:
            return _rand_null(rng)

    kinds = ['string', 'number', 'boolean', 'null', 'array', 'object']
    weights = [0.28, 0.2, 0.15, 0.07, 0.15, 0.15]
    t = rng.choices(kinds, weights=weights, k=1)[0]
    if t == 'string':
        return _rand_json_string(rng)
    if t == 'number':
        return _rand_number(rng)
    if t == 'boolean':
        return _rand_boolean(rng)
    if t == 'null':
        return _rand_null(rng)
    if t == 'array':
        return _rand_array(rng, depth, budget)
    return _rand_object(rng, depth, budget)

def _surround_with_ws(rng: random.Random, s: str) -> str:
    # Add optional leading/trailing whitespace to satisfy APIs that allow it
    ws_chars = [' ', '\t', '\r', '\n']
    def make_ws(max_len: int) -> str:
        return ''.join(rng.choice(ws_chars) for _ in range(rng.randint(0, max_len)))
    return make_ws(8) + s + make_ws(8)

def _construct_valid_for_specific_paths(rng: random.Random) -> str:
    # Occasionally emit shapes specifically tailored to certain stubs:
    choice = rng.randint(0, 9)
    if choice == 0:
        # Valid JSON string (for codec::string_t and any_codec<string>)
        return _surround_with_ws(rng, _rand_json_string(rng, 0, 96))
    if choice == 1:
        # Boolean literal
        return _surround_with_ws(rng, _rand_boolean(rng))
    if choice == 2:
        # Null literal (used by many code paths)
        return _surround_with_ws(rng, 'null')
    if choice == 3:
        # Small integer
        return _surround_with_ws(rng, str(rng.randint(-1000, 1000)))
    if choice == 4:
        # Array of strings (for array_t<std::vector<std::string>>)
        n = rng.randint(0, 6)
        arr = '[' + ','.join(_rand_json_string(rng, 0, 32) for _ in range(n)) + ']'
        return _surround_with_ws(rng, arr)
    if choice == 5:
        # Tuple-like array [string, bool]
        tup = '[' + _rand_json_string(rng, 0, 24) + ',' + _rand_boolean(rng) + ']'
        return _surround_with_ws(rng, tup)
    if choice == 6:
        # Map-like object with string keys and primitive values
        pairs = []
        for _ in range(rng.randint(0, 5)):
            key = _rand_json_string(rng, 1, 12)
            val = _rand_value(rng, 1, 256)
            pairs.append(key + ':' + val)
        return _surround_with_ws(rng, '{' + ','.join(pairs) + '}')
    if choice == 7:
        # Optional-friendly: either null or a string
        return _surround_with_ws(rng, 'null' if rng.random() < 0.5 else _rand_json_string(rng))
    if choice == 8:
        # any_value valid small values
        return _surround_with_ws(rng, rng.choice(['0', '1', 'true', 'false', 'null']))
    # Default: mixed random value with whitespace
    return _surround_with_ws(rng, _rand_value(rng, 0, 1024))


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a strategy: targeted shapes vs general random JSON
    targeted = rng.random() < 0.7
    if targeted:
        s = _construct_valid_for_specific_paths(rng)
    else:
        s = _surround_with_ws(rng, _rand_value(rng, 0, 2048))

    # Ensure size cap and avoid exceeding 4096 bytes
    b = s.encode('utf-8', errors='strict')
    if len(b) > 4096:
        # Trim safely at character boundaries by re-encoding a sliced string
        # Keep at least 2 bytes for minimal JSON tokens like [] or ""
        max_chars = max(2, int(len(s) * 4096 / max(1, len(b))) - 1)
        s2 = s[:max_chars]
        b = s2.encode('utf-8', errors='ignore')[:4096]
        # Best effort to keep valid JSON end: if we clipped inside a string, try to close it
        if b and b[-1:] == b'\\':
            b = b[:-1]
    return b

import random
import struct
import itertools

# We generate valid JSON payloads and JSON-string content because many stubs
# construct codecs over std::string, bool, encoded_value_ref, containers, etc.
# FUZZ_PARAM_STR is widely used as arbitrary byte strings which are then often
# fed into codecs that expect valid JSON strings (quoted/escaped) or arbitrary
# JSON values for any_value.
#
# Strategy:
# - Produce a small, valid JSON document chosen from several shapes:
#   - JSON string with proper escaping
#   - JSON boolean (true/false)
#   - JSON null
#   - JSON number in various formats
#   - JSON array of strings/bools/numbers
#   - JSON object with string keys and mixed simple values
# - Keep total size <= 4096 bytes
# - Randomize content deterministically via provided seed
#
# This increases the chance that:
#  - string_t encode/decode round-trips succeed
#  - boolean_t encode/decode succeeds
#  - any_value_t decode succeeds
#  - map/array/tuple/object codecs get valid inputs when needed
#  - optional/one_of/transform/enumeration paths have valid JSON to consume

_ASCII = [chr(i) for i in range(32, 127)]
_HEX = '0123456789abcdef'


def _rand_ascii(rng, n):
    return ''.join(rng.choice(_ASCII) for _ in range(n))


def _escape_json_string(s: str) -> str:
    out = []
    for ch in s:
        oc = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif oc < 0x20:
            out.append('\\u00' + _HEX[(oc >> 4) & 0xF] + _HEX[oc & 0xF])
        else:
            out.append(ch)
    return '"' + ''.join(out) + '"'


def _json_bool(rng):
    return 'true' if rng.randrange(2) else 'false'


def _json_null():
    return 'null'


def _json_number(rng):
    # Generate clean JSON numbers covering ints, negatives, decimals, exponents
    choice = rng.randrange(5)
    if choice == 0:
        return str(rng.randint(0, 10**6))
    if choice == 1:
        return '-' + str(rng.randint(0, 10**6))
    if choice == 2:
        # decimal
        a = rng.randint(0, 10**6)
        b = rng.randint(0, 999999)
        return f"{a}.{b:06d}".rstrip('0').rstrip('.')
    if choice == 3:
        # scientific positive
        a = rng.randint(0, 10**6)
        e = rng.randint(-10, 10)
        return f"{a}e{e:+d}"
    # scientific with decimal
    a = rng.randint(0, 10**6)
    b = rng.randint(0, 999)
    e = rng.randint(-10, 10)
    return f"{a}.{b:03d}E{e:+d}"


def _json_string(rng):
    # Create a medium-length JSON string with proper escaping
    ln = rng.randint(0, 64)
    raw = ''.join(chr(rng.randint(0, 127)) for _ in range(ln))
    return _escape_json_string(raw)


def _json_array_simple(rng):
    n = rng.randint(0, 8)
    elems = []
    for _ in range(n):
        kind = rng.randrange(4)
        if kind == 0:
            elems.append(_json_string(rng))
        elif kind == 1:
            elems.append(_json_bool(rng))
        elif kind == 2:
            elems.append(_json_number(rng))
        else:
            elems.append(_json_null())
    return '[' + ','.join(elems) + ']'


def _json_object_simple(rng):
    n = rng.randint(0, 6)
    items = []
    used = set()
    for _ in range(n):
        # create a printable ASCII key to help map codecs
        key_len = rng.randint(1, 12)
        key = ''.join(chr(rng.randint(97, 122)) for _ in range(key_len))
        if key in used:
            continue
        used.add(key)
        kind = rng.randrange(4)
        if kind == 0:
            val = _json_string(rng)
        elif kind == 1:
            val = _json_bool(rng)
        elif kind == 2:
            val = _json_number(rng)
        else:
            val = _json_null()
        items.append(_escape_json_string(key) + ':' + val)
    return '{' + ','.join(items) + '}'


def _top_level_json(rng):
    choice = rng.randrange(8)
    if choice == 0:
        return _json_string(rng)
    if choice == 1:
        return _json_bool(rng)
    if choice == 2:
        return _json_null()
    if choice == 3:
        return _json_number(rng)
    if choice == 4:
        return _json_array_simple(rng)
    if choice == 5:
        return _json_object_simple(rng)
    if choice == 6:
        # tuple-like array [string, bool]
        return '[' + _json_string(rng) + ',' + _json_bool(rng) + ']'
    # map<string,string> like
    obj = '{' + _escape_json_string('name') + ':' + _json_string(rng) + ',' + _escape_json_string('flag') + ':' + _json_bool(rng) + '}'
    return obj


def _wrap_for_multiple_stubs(rng, core: str) -> str:
    # Some stubs expect valid JSON value alone; others use FUZZ_PARAM_STR as raw string payloads
    # for encoding. We'll prepend a valid JSON string literal (for string codecs) separated by
    # whitespace/newlines to allow decode of first value and leave trailing space acceptable.
    # Structure:
    #   <valid JSON value>\n\n<random raw bytes as plain text for string payloads>
    tail_len = rng.randint(0, 512)
    tail = ''.join(chr(rng.randint(0, 255)) for _ in range(tail_len))
    return core + "\n\n" + tail


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a valid JSON core first
    core = _top_level_json(rng)
    payload = _wrap_for_multiple_stubs(rng, core)
    # Ensure size bound
    b = payload.encode('utf-8', errors='ignore')
    if len(b) > 4096:
        b = b[:4096]
    return b
